const bigWord = (t, a, b, txtS, cx, cy, col, size) => x => { const s = span(t, a, b); if (s <= 0.01) return; x.save(); x.translate(cx, cy); x.scale(s, s); x.rotate(-0.04); x.font = `${size || 64}px ${HAND}`; x.textAlign = 'center'; x.textBaseline = 'middle'; x.lineWidth = 10; x.strokeStyle = '#1e1612'; x.strokeText(txtS, 0, 0); x.fillStyle = col || '#f2c83a'; x.fillText(txtS, 0, 0); x.restore(); };
